SELECT A.STATUS_CD, A.ROOT_ORDER_ID, A.PAR_ORDER_ID, A.X_VEHICLE_ID, A.DB_LAST_UPD, A.CREATED, B.ORDER_NUM, B.STATUS_CD
FROM SIEBEL.S_ORDER A, SIEBEL.S_ORDER B 
WHERE 
A.ORDER_TYPE_ID = '1-7N9K' AND A.ROOT_ORDER_ID = '1-7VIK-1' AND
A.PAR_ORDER_ID = B.ROW_ID;

UPDATE SIEBEL.S_ORDER SET DB_LAST_UPD = SYSDATE, STATUS_CD = Cancelled, ROOT_ORDER_ID = ROOT_ORDER_ID || '_DUMMY', PAR_ORDER_ID = PAR_ORDER_ID || '_DUMMY', X_VEHICLE_ID = X_VEHICLE_ID || '_DUMMY' WHERE ROW_ID = '';
SELECT X_SALES_ORDER_ID, ORDER_ID FROM SIEBEL.S_ORDER_ITEM WHERE ORDER_ID = '1-3NUL-1';
UPDATE SIEBEL.S_ORDER_ITEM SET DB_LAST_UPD = SYSDATE, X_SALES_ORDER_ID = X_SALES_ORDER_ID || '_DUMMY' WHERE ORDER_ID = '';

select * from siebel.S_SRM_DATA WHERE DATA_VAL LIKE '%2-AVYC36%';
SELECT ROW_ID FROM SIEBEL.S_SHIPMENT WHERE SHIP_NUM = 'O050372879';
SELECT * FROM SIEBEL.S_SRM_REQUEST WHERE ROW_ID = '2-AVYC3B';
